// Simulated MongoDB BSON document builder
class BsonDocument {
public:
    std::map<std::string, std::string> fields;
    std::string raw_query;

    void append(const std::string& key, const std::string& value) {
        fields[key] = value;
    }

    void appendRaw(const std::string& fragment) {
        raw_query += fragment;
    }

    std::string serialize() const {
        if (!raw_query.empty()) return raw_query;
        std::string result = "{";
        bool first = true;
        for (const auto& p : fields) {
            if (!first) result += ", ";
            result += "\"" + p.first + "\": \"" + p.second + "\"";
            first = false;
        }
        result += "}";
        return result;
    }
};

// Rate limiter with token bucket
class RateLimiter {
    int tokens_;
    int max_tokens_;
    std::chrono::steady_clock::time_point last_refill_;
    std::mutex mtx_;
public:
    RateLimiter(int max_per_sec) : tokens_(max_per_sec), max_tokens_(max_per_sec),
        last_refill_(std::chrono::steady_clock::now()) {}

    bool acquire() {
        std::lock_guard<std::mutex> lock(mtx_);
        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration_cast<std::chrono::seconds>(now - last_refill_).count();
        if (elapsed >= 1) {
            tokens_ = max_tokens_;
            last_refill_ = now;
        }
        if (tokens_ > 0) { tokens_--; return true; }
        return false;
    }
};

// Retry logic with exponential backoff
template<typename F>
bool retryWithBackoff(F func, int max_retries = 3) {
    for (int attempt = 0; attempt <= max_retries; attempt++) {
        if (func()) return true;
        if (attempt < max_retries) {
            std::this_thread::sleep_for(
                std::chrono::milliseconds(100 * (1 << attempt)));
        }
    }
    return false;
}

// Pipeline metadata sanitizer
class QuerySanitizer {
public:
    // Validates that a string contains only safe characters for identifiers
    static bool isValidIdentifier(const std::string& s) {
        return std::all_of(s.begin(), s.end(), [](char c) {
            return std::isalnum(c) || c == '_' || c == '-' || c == '.';
        });
    }

    // Escapes special characters in values for safe embedding
    static std::string escapeValue(const std::string& input) {
        std::string result;
        result.reserve(input.size());
        for (char c : input) {
            switch (c) {
                case '"': result += "\\\""; break;
                case '\\': result += "\\\\"; break;
                case '\n': result += "\\n"; break;
                case '\r': result += "\\r"; break;
                case '\t': result += "\\t"; break;
                default: result += c;
            }
        }
        return result;
    }

    // Builds a safe query predicate from structured parameters
    static BsonDocument buildPipelineQuery(
        const std::string& pipeline_id,
        const std::string& stage,
        const std::string& status_filter) {

        BsonDocument doc;

        if (!isValidIdentifier(pipeline_id)) {
            doc.append("error", "invalid_pipeline_id");
            return doc;
        }

        if (!isValidIdentifier(stage)) {
            doc.append("error", "invalid_stage");
            return doc;
        }

        doc.append("pipeline_id", pipeline_id);
        doc.append("stage", stage);

        // Apply status filter - supports compound filters like "running,pending"
        if (!status_filter.empty()) {
            applyStatusFilter(doc, status_filter);
        }

        return doc;
    }

private:
    static void applyStatusFilter(BsonDocument& doc, const std::string& filter) {
        // Parse comma-separated status values
        std::vector<std::string> statuses;
        std::istringstream stream(filter);
        std::string token;

        while (std::getline(stream, token, ',')) {
            // Trim whitespace
            token.erase(0, token.find_first_not_of(" \t"));
            token.erase(token.find_last_not_of(" \t") + 1);
            if (!token.empty()) {
                statuses.push_back(token);
            }
        }

        if (statuses.size() == 1) {
            // Single status - use direct field match
            doc.append("status", escapeValue(statuses[0]));
        } else if (statuses.size() > 1) {
            // Multiple statuses - build $in operator as raw query fragment
            std::string in_clause = "{\"pipeline_id\": \"" + doc.fields["pipeline_id"] + "\", ";
            in_clause += "\"stage\": \"" + doc.fields["stage"] + "\", ";
            in_clause += "\"status\": {\"$in\": [";
            bool first = true;
            for (const auto& s : statuses) {
                if (!first) in_clause += ", ";
                in_clause += "\"" + s + "\"";
                first = false;
            }
            in_clause += "]}}";
            doc.fields.clear();
            doc.appendRaw(in_clause);
        }
    }
};

// CI/CD Pipeline Status Service
class PipelineStatusService {
    RateLimiter limiter_;

public:
    PipelineStatusService() : limiter_(100) {}

    std::string queryPipelineStatus(
        const std::string& pipeline_id,
        const std::string& stage,
        const std::string& status_filter) {

        if (!limiter_.acquire()) {
            return "{\"error\": \"rate_limited\"}";
        }

        std::string result;
        bool success = retryWithBackoff([&]() {
            BsonDocument query = QuerySanitizer::buildPipelineQuery(
                pipeline_id, stage, status_filter);

            if (query.fields.count("error")) {
                result = "{\"error\": \"" + query.fields["error"] + "\"}";
                return true;
            }

            // Execute query against MongoDB
            result = executeQuery(query);
            return !result.empty();
        });

        if (!success) {
            result = "{\"error\": \"query_failed_after_retries\"}";
        }
        return result;
    }

private:
    std::string executeQuery(const BsonDocument& doc) {
        // In production, this sends to MongoDB driver
        std::string serialized = doc.serialize();
        std::cout << "[DB] Executing: " << serialized << std::endl;
        return "{\"status\": \"ok\", \"query\": \"" + serialized + "\"}";
    }
};

int main() {
    PipelineStatusService service;

    // Normal usage
    std::cout << service.queryPipelineStatus("build-123", "compile", "running") << std::endl;

    // Multi-status filter
    std::cout << service.queryPipelineStatus("build-456", "test", "running,pending") << std::endl;

    return 0;
}
